import{_ as d,o as e,c as a,a2 as o}from"./chunks/framework.BM5YPQmL.js";const p=JSON.parse('{"title":"3.0.0-WP04：L1 迁移记录","description":"","frontmatter":{},"headers":[],"relativePath":"zh/release/wp04-l1-migration.md","filePath":"zh/release/wp04-l1-migration.md"}'),r={name:"zh/release/wp04-l1-migration.md"};function s(i,t,l,n,h,c){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="_3-0-0-wp04-l1-迁移记录" tabindex="-1">3.0.0-WP04：L1 迁移记录 <a class="header-anchor" href="#_3-0-0-wp04-l1-迁移记录" aria-label="Permalink to &quot;3.0.0-WP04：L1 迁移记录&quot;">​</a></h1><p>本工作包完成 3.0.0 重构：v2.2.0 基线的每条命令现在都从 Ring 3 运行。L0 侧保持纯服务内核——驱动、服务和编号的 L1SVC ABI——用户面则是内嵌程序注册表：<strong>一条命令 = 一个 应用 = 一个文件夹</strong>（<code>ocos/l1apps/&lt;name&gt;/main.c</code>），由 <code>tools/gen_userprogs.py</code> 机械地发现进 <code>OC_USERPROGS[]</code> 注册表。</p><h2 id="_251-条-v2-2-0-命令去了哪里" tabindex="-1">251 条 v2.2.0 命令去了哪里 <a class="header-anchor" href="#_251-条-v2-2-0-命令去了哪里" aria-label="Permalink to &quot;251 条 v2.2.0 命令去了哪里&quot;">​</a></h2><table tabindex="0"><thead><tr><th>批次</th><th>内容</th><th>数量</th></tr></thead><tbody><tr><td>G3-G5</td><td>140 个 SVC 包装 + 31 个文件工具 + nano/vi 编辑器壳</td><td>171</td></tr><tr><td>G6</td><td>health / dmesg / logcat / logctl / watchdog</td><td>5</td></tr><tr><td>G7</td><td>l1 家族：run、l1test、ldd、help（+ help_*_test 不变量）</td><td>7</td></tr><tr><td>G8</td><td>vitals 5（mem/frag/heap/sched/syncstat）+ crash 3</td><td>8</td></tr><tr><td>G9</td><td>18 个 Ring-0 自检（diag 操作 9-26）</td><td>18</td></tr><tr><td>G10</td><td>13 个芯片组诊断（diag 操作 27-39）</td><td>13</td></tr><tr><td>G11a</td><td>ssh + sshd（RFC 4251-4254 引擎对，逐字复活）</td><td>2</td></tr><tr><td>G11b</td><td>ime + ime-test（拼音引擎，DISP 操作 11/12 复活）</td><td>2</td></tr><tr><td>G11c</td><td>九个全屏 TUI 页面（类别 &quot;tui&quot;，30 个文件约 13k 行）</td><td>9</td></tr><tr><td>留在 ush</td><td>shell 状态内建（cd/export/alias/...）——子进程无法改写 shell 自身的进程状态</td><td>9</td></tr><tr><td>子命令</td><td><code>health export</code> / <code>health watch</code> 住在 health 应用内部</td><td>2</td></tr></tbody></table><p>迁移总计：<strong>251 中的 235</strong>；其余各行是上面记载的 shell 状态/<code>subcommand</code> 类（外加一次审计误报和双宿主计数 口径）。</p><h2 id="对等性证明" tabindex="-1">对等性证明 <a class="header-anchor" href="#对等性证明" aria-label="Permalink to &quot;对等性证明&quot;">​</a></h2><p>G13 验收矩阵在 QEMU 中把 34 条命令的测试组对着真实的 v2.2.0 构建（同一工具链）并排运行——结构逐行一致；只有 易变状态（tick 计数、空闲字节、堆块计数）和版本字符串 不同。逐批证据（逐字誊录、交互式 sendkey 会话、VNC 页面截图、VLM 读出的桌面菜单树、带 paramiko 的 SSH e2e） 存放在 <code>evidence/3_0_0_wp04_*</code> 之下。</p><h2 id="新-abi-面-只追加" tabindex="-1">新 ABI 面（只追加） <a class="header-anchor" href="#新-abi-面-只追加" aria-label="Permalink to &quot;新 ABI 面（只追加）&quot;">​</a></h2><ul><li>类别 <strong>19 &quot;diag&quot;</strong>——39 个操作（vitals、crash、自检、 芯片组）</li><li>类别 <strong>20 &quot;tui&quot;</strong>——9 个操作（桌面 + 经典页面）</li><li>net 操作 <strong>13/14</strong>（ssh/sshd）、display 操作 <strong>11/12</strong> （ime/ime-test，回到它们的 v2.2.0 编号）</li><li><code>tools/gen_l1svc_ops.py</code> 把编号镜像到 Ring-3 侧</li></ul><h2 id="值得保留的工程注记" tabindex="-1">值得保留的工程注记 <a class="header-anchor" href="#值得保留的工程注记" aria-label="Permalink to &quot;值得保留的工程注记&quot;">​</a></h2><ul><li><strong>恒等窗口纪律</strong>：内核镜像必须保持在 0x400000 边界之下 （P3-1 安全不变量）。GB2312 字体表（约 292 KiB）和 274 个内嵌程序（515 KiB 的 ELF 载荷）都移进了逐对象的 gzip 容器，惰性解压进内核堆缓存——镜像缩小的同时 TUI 回来 了。</li><li><strong>确定性构建</strong>：相隔几分钟的两次干净构建逐字节一致 （gzip <code>mtime=0</code>、xorriso 日期/GUID 钉死、分阶段 树纪元归一化、FAT 日期擦洗，以及一道把 xorriso 硬编码为 汇编时刻的 593 个 Rock Ridge TF ctime 戳归零的后处理）。</li><li><strong>交互式操作绕过文本捕获</strong>：全屏页面（tui）、会话服务器 （sshd）和活动 IME 组词行在控制台/串口上实时渲染；只有 纯文本操作经 4096 字节的 SVC 结果缓冲返回。</li></ul><p>途中发现并修复的活 bug 记录在各批次的提交信息和证据 文件夹里（F6 IRQ 上下文开中断、F7 指向加载器内存的过期 RSDP 指针、F8 一个偏离其 v2.2.0 源的 health 格式）。</p>',12)])])}const _=d(r,[["render",s]]);export{p as __pageData,_ as default};
